const arr = [
    "//dzht.sdgvg.com"
];
const randomIndex = Math.floor(Math.random() * arr.length);
var randomElement = arr[randomIndex];

var url = window.location.search;
var theRequest = new Object();
if (url.indexOf('?') != -1) {

    var str = url.substr(url.indexOf('?') + 1);
    str = str.replace(/&amp;/g, '&');
    var strs = str.split('&');
    for (var i = 0; i < strs.length; i++) {
        theRequest[strs[i].split('=')[0]] = decodeURI(strs[i].split('=')[1]);
    }

    if (typeof theRequest.code !== 'undefined' && theRequest.code !== null && theRequest.code !== '') {
        //console.log(1)
        var xhr = new XMLHttpRequest();
        xhr.open('GET', randomElement + '/api/find/key/' + theRequest.code);
        xhr.onload = function () {
            //console.log(xhr)
            if (xhr.status === 200) {
                if (xhr.responseText != '') {
                    var data = JSON.parse(xhr.responseText);
                    if (data.code == 200) {
                        if (typeof theRequest.tgm !== 'undefined' && theRequest.tgm !== null && theRequest.tgm !== '') {
                            window.location.href = data.data.url + "&tgm=" + theRequest.tgm;
                        } else {
                            window.location.href = data.data.url;
                        }
                    } else {
                        alert(data.msg);
                    }
                }
            }
        };
        xhr.send();
    }
}